// Chaque règle : { color, a, b, c } où a=#id, b=.classe, c=type.
// Renvoie la couleur gagnante selon la spécificité, l'ordre départageant les égalités.
export function winningColor(rules) {
  // BUG : renvoie la dernière règle, en ignorant la spécificité.
  return rules[rules.length - 1].color;
}

